#include <stdio.h>

int f(int a, int b) {
    if(a == 1) return 1;
    else return b * f(a-1, b);
}

int main()
{
    printf("%d\n", f(5, 6));
    return 0;
}

#include <stdio.h>

int f(int a) {
    if(a <= 1) return 1;
    return f(a-1) * 2 + f(a-3) * 5;
}

int main()
{
    printf("%d\n", f(4));
}

